// Deterministic Nadi work-submission evidence uses existing identity and open sessions.
// It is best effort and never changes the success of MPC or CPD submission.
export async function recordNadiWork(env,user,label){if(!env.DB||!user)return;try{const e=await q(env.DB,'SELECT employee_id FROM employees WHERE active=1 AND account_user_id=? AND lower(email)=lower(?)',user.userId,user.email).first();if(!e)return;const session=await q(env.DB,'SELECT id FROM attendance_sessions WHERE employee_id=? AND clock_out IS NULL AND break_start IS NULL',e.employee_id).first();if(!session)return;const stamp=now(),recent=await q(env.DB,'SELECT recorded_at FROM attendance_trace WHERE session_id=? AND task=? ORDER BY recorded_at DESC,rowid DESC LIMIT 1',session.id,label).first();if(recent&&seconds(recent.recorded_at,stamp)<300)return;await q(env.DB,'INSERT INTO attendance_trace (id,employee_id,session_id,recorded_at,active_seconds,idle_seconds,status,task,monitor_json) VALUES (?,?,?,?,0,0,?,?,?)',crypto.randomUUID(),e.employee_id,session.id,stamp,'Available',label,JSON.stringify({kind:'submission'})).run()}catch{console.error('Optional Nadi work trace unavailable')}}
